/* Catechism data — English. Loaded before js/catechisme.js.
   After the “Catechism of the Orthodox Church in Contemporary Language”
   (Deacon Roman Biliavskyi, ROCOR, 2018), translated from the French
   adaptation; answers reworded and condensed; “n” = question number in the book. */
window.CATECHISM_DATA = {
  chapters: [
    { id: 0, short: "Introduction", title: "The Symbol of Faith" },
    { id: 1, short: "Article 1", title: "Faith, the Trinity, Creation" },
    { id: 2, short: "Article 2", title: "The only-begotten Son of God" },
    { id: 3, short: "Article 3", title: "Sin, salvation and the Incarnation" },
    { id: 4, short: "Article 4", title: "The Cross" },
    { id: 5, short: "Article 5", title: "The Resurrection" },
    { id: 6, short: "Article 6", title: "The Ascension" },
    { id: 7, short: "Article 7", title: "Judgement and the Kingdom" },
    { id: 8, short: "Article 8", title: "The Holy Spirit" },
    { id: 9, short: "Article 9", title: "The Church" },
    { id: 10, short: "Article 10", title: "Baptism and the Mysteries" },
    { id: 11, short: "Article 11", title: "The resurrection of the dead" },
    { id: 12, short: "Article 12", title: "The life of the age to come" }
  ],
  items: [
    { c: 0, n: 1, q: "Where is the Orthodox faith expressed in summary form?", a: "In the Symbol of Faith, or Creed: it sets out briefly and precisely what Orthodox Christians believe." },
    { c: 0, n: 2, q: "What does the word “symbol” mean?", a: "From the Greek <em>symbolon</em>, “that which fits together”. In the past, a betrothed man setting off on a long journey would break a stick in two and leave one half with his beloved: on his return, the two pieces had to fit perfectly. The Symbol of Faith is the half God has entrusted to us so that we may find him again; it is also a key that must match its lock exactly. That is why nothing may be added to it or taken away from it." },
    { c: 0, n: 3, q: "What is the Symbol of Faith about?", a: "It unfolds Christ’s command: “Baptise them in the name of the Father, and of the Son, and of the Holy Spirit” (Matt 28:19). It presents the Father the Creator, the Son crucified and risen for us, and the Spirit who gives life: not three names, but the one name of God, the consubstantial and undivided Trinity." },
    { c: 0, n: 4, q: "How is the Symbol of Faith divided?", a: "Into twelve articles: 1. God the Father, Creator; 2. the only-begotten Son, born before all ages; 3. his incarnation; 4. his crucifixion; 5. his resurrection; 6. his ascension; 7. his return in glory; 8. the Holy Spirit; 9. the Church; 10. baptism; 11. the resurrection of the dead; 12. the life of the age to come. The full text is in the “Symbol of Faith” section." },
    { c: 0, n: 5, q: "Who formulated the Creed?", a: "The Fathers of the First Ecumenical Council of Nicaea (325) drew up the first seven articles, and those of the Second Council of Constantinople (381) the last five. Hence its name, the Nicene-Constantinopolitan Creed." },
    { c: 0, n: 6, q: "What is an ecumenical council?", a: "A universal assembly of the bishops of all the local Churches, gathered to express the apostolic faith, respond to heresies and manifest the unity of Christians. Its model is the council of the Apostles in Jerusalem (Acts 15), which concluded: “It seemed good to the Holy Spirit and to us…”." },
    { c: 0, n: 7, q: "How many ecumenical councils have there been?", a: "Seven: Nicaea I (325), Constantinople I (381), Ephesus (431), Chalcedon (451), Constantinople II (553), Constantinople III (680-681) and Nicaea II (787), which defended the veneration of icons." },
    { c: 0, n: 8, q: "Where does the tradition of councils come from?", a: "From the council of the Apostles in Jerusalem, in the middle of the 1st century (Acts 15). It had to decide whether pagans who became Christians had to keep the whole law of Moses. Guided by the Spirit — “It seemed good to the Holy Spirit and to us” — the Apostles retained only a few essential obligations. Ever since, the Church has settled the great questions of faith in council." },
    { c: 1, n: 9, q: "Why does the Creed say “I believe” and not “We believe”?", a: "The Lord’s Prayer begins with “Our”, because the heavenly Father is common to all. But the profession of faith demands a personal commitment: it is I who confess the Trinity with my heart and my lips, and no one can do it in my place." },
    { c: 1, n: 10, q: "Can one believe in one’s heart without confessing one’s faith?", a: "No: “With the heart man believeth unto righteousness; and with the mouth confession is made unto salvation” (Rom 10:10). True faith is spoken and lived." },
    { c: 1, n: 11, q: "What does “believing in God” mean?", a: "It means first believing that he exists, but above all trusting him, entrusting oneself to his providence, loving him and doing his will. Faith is “the substance of things hoped for, the evidence of things not seen” (Heb 11:1)." },
    { c: 1, n: 12, q: "Where does faith come from?", a: "“Faith cometh by hearing, and hearing by the word of God” (Rom 10:17). That is why the Church prays that God may send labourers to proclaim the Gospel." },
    { c: 1, n: 13, q: "How can one experience faith?", a: "By living in the Church, the faith received through the word becomes personal experience. As the Samaritans said to the woman who had told them about Jesus: “Now we believe, not because of thy saying: for we have heard him ourselves” (John 4:42)." },
    { c: 1, n: 14, q: "Is it enough to be a good person, whatever one believes?", a: "All goodness comes from God as a river comes from its source: “There is none good but one, that is, God” (Mark 10:18). Man becomes truly good by cleaving to God through faith. The catechism’s introduction recalls Abba Agathon, who accepted every insult but refused to be called a heretic: “heresy is separation from God”." },
    { c: 1, n: 15, q: "Can one please God without faith?", a: "Scripture answers: “Without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him” (Heb 11:6). Faith is not a badge of superiority: it is the relationship of trust that opens us to God. He alone knows each person’s heart." },
    { c: 1, n: 16, q: "What is the link between faith and good works?", a: "Faith comes first: it is faith that justifies, as with Abraham. But faith without works is dead (Jas 2:26): living faith necessarily shows itself in love put into action. Works do not “earn” salvation; they are the fruit of true faith." },
    { c: 1, n: 17, q: "Are there other gods besides the Creator?", a: "No. The God in whom we believe is the one God of all people, even of those who do not believe in him: “To us there is but one God, the Father, of whom are all things… and one Lord Jesus Christ, by whom are all things” (1 Cor 8:6)." },
    { c: 1, n: 18, q: "Can we know the essence of God?", a: "No. The essence of God remains beyond the grasp of men and angels alike: he “dwells in light unapproachable” (1 Tim 6:16). No word can describe it." },
    { c: 1, n: 19, q: "How then can we know a wholly transcendent God?", a: "Through his <strong>energies</strong> (from the Greek <em>energeia</em>, “force in action”): his eternal actions, his grace. They are what is manifested in creation, in Scripture and in the lives of the saints." },
    { c: 1, n: 20, q: "What is the nature of these divine energies?", a: "They are not created: they shine forth eternally from God’s essence, like the rays of the sun, without being separated from it. It is by sharing in the divine energies that man becomes a partaker of the divine nature (2 Pet 1:4)." },
    { c: 1, n: 21, q: "How does Scripture speak of God’s actions?", a: "It expresses them through his names and attributes: God is called Good, Holy, Just, Wise, Almighty, Love… Each of these names expresses a way in which God acts and makes himself known to us." },
    { c: 1, n: 22, q: "What are the attributes of God?", a: "God is <strong>Spirit</strong>: immaterial and simple, without parts; he does not merely “have” love or wisdom, he <em>is</em> Love and Wisdom, and in him love and justice are not opposed. He is <strong>eternal</strong>: above time, which he created. He is <strong>present everywhere</strong> without mixing with anything: “Whither shall I flee from thy presence?” (Ps 139:7). He is also unchanging, almighty, all-knowing, perfectly good, holy and free." },
    { c: 1, n: 23, q: "If God is Spirit, why does the Bible speak of his eyes and hands?", a: "These are <em>anthropomorphisms</em>: human images expressing spiritual realities in our limited language. God’s “eyes” speak of his omniscience, his “hand” of his power, his “face” of his presence." },
    { c: 1, n: 24, q: "Why say that God is one in three Persons?", a: "Jews, Muslims and some philosophers also know that God is one. But to Christians his inner, personal life has been revealed — like visitors who see a palace only from outside, while others are invited in. The first name the Creed gives God is “Father”: God is one in three Persons, the Father, the Son and the Holy Spirit." },
    { c: 1, n: 25, q: "What is the difference between “person” (hypostasis) and “essence” (nature)?", a: "Essence refers to what is common (“what?”): all people share human nature. Hypostasis refers to what is unique (“who?”): Peter, Paul, John. In God there is one essence and three Persons." },
    { c: 1, n: 26, q: "In what are the three Persons of the Trinity equal?", a: "They have the same divine dignity, the same nature, the same will and the same power: the Father is true God, the Son is true God, the Spirit is true God, and yet there is only one God." },
    { c: 1, n: 27, q: "In what are the three Persons distinct?", a: "By their personal properties: the Father is neither begotten nor proceeding; the Son is begotten of the Father; the Spirit proceeds from the Father." },
    { c: 1, n: 28, q: "Can we understand this “heavenly arithmetic”?", a: "No: the mystery of the Trinity entirely surpasses reason. Yet it is the heart of the Christian faith, because it is what God himself has revealed to us about himself. We do not comprehend it; we worship and live by it." },
    { c: 1, n: 29, q: "Are there images to help approach the Trinity?", a: "The Fathers proposed some, while knowing their limits. The sun: the disc (the Father), the light that reaches us (the Son), the warmth that gives us life (the Spirit) — one single sun. Or the human soul, with its mind, word and breath." },
    { c: 1, n: 30, q: "Does the Old Testament already speak of the Trinity?", a: "In a veiled way, so as not to unsettle Israel’s faith in the one God. But there are signs: from Genesis 1:1, the name of God (<em>Elohim</em>) is plural and the verb “to create” singular; God says “Let us make man in our image” (Gen 1:26); the seraphim sing “Holy” three times (Isa 6:3); and three visitors appear to Abraham at Mamre (Gen 18)." },
    { c: 1, n: 31, q: "Where does the New Testament reveal the Trinity?", a: "At the baptism of Christ, where the Father’s voice is heard and the Spirit descends like a dove (Matt 3:16-17); in the command to baptise “in the name of the Father, and of the Son, and of the Holy Spirit” (Matt 28:19); in St Paul’s blessing: “The grace of the Lord Jesus Christ, and the love of God, and the communion of the Holy Spirit” (2 Cor 13:14)." },
    { c: 1, n: 32, q: "Why did God reveal the mystery of the Trinity to us?", a: "So that man might truly know his Creator and glorify him rightly — which is precisely what the word “Orthodoxy” means." },
    { c: 1, n: 33, q: "Why is it important to know that God is Father?", a: "Because through baptism God truly becomes our Father, and we can say to him “Our Father”." },
    { c: 1, n: 34, q: "Why is it important to know that Jesus is the Son of God?", a: "Because by being united to the only-begotten Son, we in turn become sons and daughters of God by adoption." },
    { c: 1, n: 35, q: "Why is it important to know that the Spirit proceeds from the Father?", a: "Because by receiving the anointing of the Spirit we ourselves enter into a “passage”, a movement towards God. It is no accident that the greatest Christian feast is called Pascha, a word that means precisely “passage”." },
    { c: 1, n: 36, q: "What does “God Almighty” mean?", a: "In Greek <em>Pantocrator</em>, “the one who holds all things”. God keeps everything in existence and cares for the least of his creatures: “Not one sparrow shall fall on the ground without your Father” (Matt 10:29)." },
    { c: 1, n: 37, q: "Why is God called “Creator”?", a: "Because “all things were made by him; and without him was not any thing made that was made” (John 1:3)." },
    { c: 1, n: 38, q: "How did God create the universe?", a: "Out of nothing (<em>ex nihilo</em>), without pre-existing matter, by his word and will alone: “He spake, and it was done” (Ps 33:9)." },
    { c: 1, n: 39, q: "Why did God create the world?", a: "Out of love. Love always seeks to share its joy: God willed beings capable of communing in his eternal love, of loving him and being loved by him." },
    { c: 1, n: 40, q: "Could God have chosen not to create the world?", a: "Yes. He had no need of it: the Father, the Son and the Spirit live from all eternity in the fullness of love. Creation is a free gift, the fruit of the overflowing of that love." },
    { c: 1, n: 41, q: "What are the “things invisible” of the Creed?", a: "The spiritual world, invisible to our eyes, to which the angels belong." },
    { c: 1, n: 42, q: "Who are the angels?", a: "Good, intelligent, bodiless and mighty spirits, in the service of God, “sent forth to minister for them who shall be heirs of salvation” (Heb 1:14). “Angel” means “messenger”." },
    { c: 1, n: 43, q: "Who was created first, the angels or human beings?", a: "The angels. The invisible world was created before the visible one: when God laid the foundations of the earth, “all the sons of God shouted for joy” (Job 38:7)." },
    { c: 1, n: 44, q: "How are the angels organised?", a: "In three triads: Seraphim, Cherubim, Thrones; Dominions, Virtues, Powers; Principalities, Archangels, Angels." },
    { c: 1, n: 45, q: "What is a guardian angel?", a: "An angel God gives to each person, and even to each nation, to protect them and guide them to salvation: “He shall give his angels charge over thee, to keep thee in all thy ways” (Ps 91:11). Christ says of little children that “their angels do always behold the face of my Father” (Matt 18:10)." },
    { c: 1, n: 46, q: "Who is Satan?", a: "An angel of light who, out of pride and envy, sought to raise himself above God and broke away from his Creator. He is called the “devil” (the divider) and the “father of lies”." },
    { c: 1, n: 47, q: "Who are the demons?", a: "Angels created good who freely followed Satan in rebellion. They have attached themselves to pride and hatred, and seek to draw people away from God. But they have no power over anyone who abides in Christ." },
    { c: 1, n: 48, q: "What is evil, and where does it come from?", a: "Evil is not a “substance” created by God: it arises from the ill will of free beings — fallen angels and human beings — who turn away from God. Just as darkness is the absence of light, evil is a moving away from the Good." },
    { c: 1, n: 49, q: "What does Scripture say about the creation of the world?", a: "That in the beginning God created heaven and earth, then in six days the light, the firmament, dry land and plants, the heavenly bodies, fish and birds, animals and finally man. On the seventh day God rested: this is the origin of the Sabbath, the day of rest. The Church reads this account as a revelation of the order and goodness of the creation God willed." },
    { c: 1, n: 50, q: "Was the world created as we see it today?", a: "No. Everything had been created good, beautiful and without violence. The present world bears the wounds of man’s fall, and it too awaits its liberation (Rom 8:21)." },
    { c: 1, n: 51, q: "How did God create man?", a: "Alone among all creatures, man is created after a kind of “council” of the Trinity: “Let us make man in our image, after our likeness” (Gen 1:26). God forms him from the earth and breathes into him the breath of life: man unites in himself the visible and the spiritual worlds." },
    { c: 1, n: 52, q: "How did God create woman?", a: "“The Lord God caused a deep sleep to fall upon Adam… and he took one of his ribs, and made he a woman, and brought her unto the man” (Gen 2:21-22). Man and woman are of the same nature, made for each other." },
    { c: 1, n: 53, q: "Why is Eve taken from Adam’s rib?", a: "The rib protects the heart: the image speaks of the closeness and mutual love of man and woman in God’s plan, and of the unity of all humanity, issuing from one body." },
    { c: 1, n: 54, q: "What does the “image of God” in man consist of?", a: "Everything that distinguishes us from animals and brings us close to the Creator: being a person, intelligence, freedom, will, speech, creativity, the immortality of the soul, responsibility for creation. The image is given to us; it can be obscured, never destroyed." },
    { c: 1, n: 55, q: "And the “likeness” of God?", a: "It is likeness through the virtues: love, joy, peace, patience, goodness, gentleness, self-control. God is love: the person who loves becomes like him. The image is a gift; the likeness a task, accomplished with grace." },
    { c: 1, n: 56, q: "What is man’s vocation?", a: "To know God, love him, glorify him and become his temple, so as to become a “partaker of the divine nature” (2 Pet 1:4) — that is, god by grace." },
    { c: 1, n: 57, q: "What does “becoming god by grace” mean?", a: "It is <em>theosis</em>, or deification: becoming by God’s gift what God is by nature, without being merged with him. As iron plunged into fire becomes burning and glowing while remaining iron." },
    { c: 1, n: 58, q: "What was the garden of Eden?", a: "The paradise where the first human beings lived, both material and spiritual, where they communed directly with God. In its midst stood the tree of life, which gave immortality, and the tree of the knowledge of good and evil." },
    { c: 1, n: 59, q: "What was the tree of life?", a: "The tree of paradise whose fruit gave immortality. The Fathers see in it a figure of Christ and of the Eucharist, the “medicine of immortality”." },
    { c: 1, n: 60, q: "What is meant by divine predestination?", a: "God’s plan, even before creation, to call man to eternal happiness. Even when man turned away from it, God did not give up: he opened a new way in his Son. “He hath chosen us in him before the foundation of the world, that we should be holy… having predestinated us unto the adoption of children” (Eph 1:4-5)." },
    { c: 1, n: 61, q: "Has God predestined everyone to happiness?", a: "God “will have all men to be saved” (1 Tim 2:4). Beyond time, he foreknows each person’s free choice — to love God or to oppose him — but it is not his foreknowledge that determines that choice: man remains free and responsible." },
    { c: 1, n: 62, q: "What is divine providence?", a: "God’s constant action in the world: he keeps all creatures alive, directs them towards good, upholds all that is good, and even makes evil serve a greater good. “Take no thought for your life… your heavenly Father knoweth that ye have need of all these things” (Matt 6:25-32)." },
    { c: 1, n: 63, q: "Where does Scripture speak of providence?", a: "Notably in the Sermon on the Mount: “Behold the fowls of the air… your heavenly Father feedeth them. Are ye not much better than they?… Seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you” (Matt 6:25-33)." },
    { c: 2, n: 64, q: "What does the name “Jesus” mean?", a: "“God saves”, “the Saviour”. The angel revealed it to Joseph: “Thou shalt call his name Jesus: for he shall save his people from their sins” (Matt 1:21)." },
    { c: 2, n: 65, q: "What does the title “Christ” mean?", a: "From the Greek <em>Christos</em>, in Hebrew <em>Messiah</em>: “the Anointed One”. In the Old Testament, prophets, kings and high priests received anointing; Jesus is the Anointed One par excellence — Prophet, King and High Priest, filled with the Spirit." },
    { c: 2, n: 66, q: "Why is Jesus called “Lord”?", a: "Because he is true God: “Lord” is one of the names of God in Scripture. Jesus himself says: “Ye call me Master and Lord: and ye say well; for so I am” (John 13:13)." },
    { c: 2, n: 67, q: "Who is Jesus Christ?", a: "The eternal Son of God who became man. The Council of Chalcedon confesses him as “one and the same Son, perfect in Godhead and perfect in manhood, truly God and truly man”, in two natures “without confusion, without change, without division, without separation”." },
    { c: 2, n: 68, q: "Does Christ have two wills?", a: "Yes, a divine will and a human will, just as he has two natures. His human will freely submits to the divine will: “Not as I will, but as thou wilt” (Matt 26:39). The Sixth Ecumenical Council made this precise." },
    { c: 2, n: 69, q: "What does Scripture say about the divinity of Jesus Christ?", a: "“In the beginning was the Word… and the Word was God” (John 1:1); “Christ… who is over all, God blessed for ever” (Rom 9:5); “This is the true God, and eternal life” (1 John 5:20). Thomas, before the risen Lord, cries out: “My Lord and my God!” (John 20:28)." },
    { c: 2, n: 70, q: "What does Scripture say about the humanity of Jesus Christ?", a: "“The Word was made flesh, and dwelt among us” (John 1:14); there is “one mediator between God and men, the man Christ Jesus” (1 Tim 2:5). The Gospel shows him hungry, thirsty, tired, in anguish, weeping for his friend Lazarus, suffering and dying. Risen, he says: “Handle me, and see; for a spirit hath not flesh and bones” (Luke 24:39)." },
    { c: 2, n: 71, q: "Why is Jesus called the “only-begotten” Son of God?", a: "Because he is the only Son born of the very essence of the Father, and therefore of the same nature as him. Angels and saints are called children of God by adoption and grace; Christ is Son by nature." },
    { c: 2, n: 72, q: "When was the Son of God born of the Father?", a: "“Before all ages”: there was never a time when the Son did not exist. He is co-eternal with the Father." },
    { c: 2, n: 73, q: "What does “Light of Light” mean?", a: "An image of the eternal birth of the Son: just as the sun’s light gives rise to the light that reaches us, inseparable from it and of the same nature, the Son is born of the Father without diminishing him or being separated from him." },
    { c: 2, n: 74, q: "What does “true God of true God” mean?", a: "That the Son is God in exactly the same sense as the Father, and not a second-rank “god”. “This is the true God, and eternal life” (1 John 5:20)." },
    { c: 2, n: 75, q: "What is the difference between “begetting” and “making”?", a: "To beget is to give birth from one’s own substance; to make is to produce out of nothing or out of something else. Man begets man; God begets God. The Son is therefore “begotten, not made”: he is not a creature." },
    { c: 2, n: 76, q: "What does “of one essence with the Father” mean?", a: "The Son is of the same divine substance as the Father (Greek <em>homoousios</em>). It is the only word in the Creed not found in the Bible, chosen at Nicaea to exclude Arianism; it expresses Christ’s words: “I and my Father are one” (John 10:30)." },
    { c: 2, n: 77, q: "What does “by whom all things were made” mean?", a: "These are St John’s words: “All things were made by him; and without him was not any thing made that was made” (John 1:3). The Father creates and governs the world through his Son, in the Spirit." },
    { c: 3, n: 78, q: "“For us men”: which people does this mean?", a: "All, without exception. The Son of God did not come for one people only, but for the salvation of the whole world and of each person individually." },
    { c: 3, n: 79, q: "From what does the Son of God save us?", a: "From sin, from the curse that follows from it, from death and from the power of the devil." },
    { c: 3, n: 80, q: "What is sin?", a: "A transgression of the law of God (1 John 3:4). St John of Damascus defines it as “a voluntary departure from what is in accordance with nature to what is contrary to it”: sin disfigures us and makes us miss our goal." },
    { c: 3, n: 81, q: "Where does sin come from?", a: "From the devil, who “sinneth from the beginning”, and from man’s free consent to his temptation. But “the Son of God was manifested, that he might destroy the works of the devil” (1 John 3:8)." },
    { c: 3, n: 82, q: "When did sin enter humanity?", a: "When the devil beguiled Adam and Eve and led them to break the commandment: “Of the tree of the knowledge of good and evil, thou shalt not eat of it: for in the day that thou eatest thereof thou shalt surely die” (Gen 2:17)." },
    { c: 3, n: 83, q: "What was the tree of the knowledge of good and evil?", a: "The sign that God alone defines what is good and what is evil. By respecting it, man could freely exercise trusting obedience; by touching it, he sought to decide good and evil in God’s place." },
    { c: 3, n: 84, q: "Did Adam and Eve know evil before the fall?", a: "Only “from a distance”, without touching it — as we know that an electric socket can kill without ever having touched one. God was the source of all their knowledge and life; they had never been united with evil." },
    { c: 3, n: 85, q: "Why did God allow the possibility of the fall?", a: "Because freedom is part of the image of God, and there is no love without freedom. And freedom presupposes the possibility of choosing. God willed a freely given love, at the risk of refusal." },
    { c: 3, n: 86, q: "How was it possible to disobey God?", a: "Adam and Eve listened to the devil rather than to God. Their free will, naturally directed towards the love of God, turned towards evil." },
    { c: 3, n: 87, q: "How did the devil beguile the woman?", a: "Through doubt and lies. The serpent insinuates: “Hath God said…?”, then: “Ye shall not surely die… ye shall be as gods.” Eve looks at the fruit, desires it, eats of it and gives some to her husband (Gen 3:1-6). This is still the path of temptation today: doubt, desire, and then the act." },
    { c: 3, n: 88, q: "What did the fall consist of?", a: "First of all in disobedience — the commandment of fasting was broken. But more deeply in pride: wanting to become “as gods” without God, by one’s own strength, instead of receiving deification as a gift." },
    { c: 3, n: 89, q: "Could Adam and Eve have repented at once?", a: "Yes. But instead of weeping over their fault before God, they looked for someone to blame: Adam accuses Eve — and God who gave her to him — and Eve accuses the serpent. It was the refusal to repent that sealed the break." },
    { c: 3, n: 90, q: "What were the consequences of Adam and Eve’s sin?", a: "The curse and death." },
    { c: 3, n: 91, q: "What is the “curse” that follows the fall?", a: "Not God’s revenge, but the consequence of sin, which destroys the one who commits it. It is also a remedy: a condition suited to fallen man, to lead him to humility and repentance. The fall upset man’s relationship with God (man is afraid and hides, Gen 3:10), his inner harmony (the spirit no longer guides the soul and body, and the passions dominate), relationships between people, and the relationship with creation, which became subject to suffering." },
    { c: 3, n: 92, q: "What is death?", a: "For the Fathers, death is first of all spiritual: the separation of the soul from God, the source of life. Physical death — the separation of soul and body — is its consequence. It is not willed by God, yet it also prevents evil from becoming eternal." },
    { c: 3, n: 93, q: "What is original sin?", a: "A hereditary wound in human nature. Adam’s descendants are not personally guilty of his fault, but they bear all its consequences: mortality, inclination to sin, frailty." },
    { c: 3, n: 94, q: "Did God leave human beings a hope?", a: "Yes: right after the fall, he promises that the seed of the woman will crush the serpent’s head (Gen 3:15). This promise is called the “Protoevangelium”, the first announcement of Christ, born of the Virgin." },
    { c: 3, n: 95, q: "Did all the ancients await the Saviour?", a: "No: most peoples had forgotten the promise." },
    { c: 3, n: 96, q: "Did God renew his promise?", a: "Yes, throughout history: to Abraham (“In thy seed shall all the nations of the earth be blessed”, Gen 22:18), to Moses (“I will raise them up a Prophet… like unto thee”, Deut 18:18), to David (“I will establish the throne of his kingdom for ever”, 2 Sam 7:13), and through the prophets." },
    { c: 3, n: 97, q: "How can God, who is everywhere, “come down from heaven”?", a: "God is everywhere, in heaven as on earth. “Coming down” means that he, the Invisible, made himself visible by becoming incarnate." },
    { c: 3, n: 98, q: "Why did the Son of God come down from heaven?", a: "“The Word of God became man that we might become gods; he made himself visible in a body that we might have an idea of the invisible Father” (St Athanasius of Alexandria)." },
    { c: 3, n: 99, q: "Does “coming down from heaven” mean becoming incarnate?", a: "Yes: “The Word was made flesh” (John 1:14). The Son of God became man without ceasing to be God." },
    { c: 3, n: 100, q: "How many Persons are there in Christ?", a: "One: the divine Person of the Son. Christ is the one God-man." },
    { c: 3, n: 101, q: "How many natures does Christ have?", a: "Two: the divine nature and the human nature." },
    { c: 3, n: 102, q: "How are the two natures of Christ united?", a: "“Without confusion, without change, without division and without separation”: the divine does not mix with the human, the human is not absorbed, and yet it is one single Person." },
    { c: 3, n: 103, q: "How many wills does Christ have?", a: "Two: divine and human. His human will freely submits to the divine will: “O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt” (Matt 26:39)." },
    { c: 3, n: 104, q: "How does Christ’s humanity differ from ours?", a: "He was born of a Virgin, without a human father, and so does not inherit the wound of original sin; he never committed sin. He voluntarily took upon himself our blameless weaknesses: hunger, fatigue, suffering, death." },
    { c: 3, n: 105, q: "How many times was Christ born?", a: "Twice: of the Father, without a mother, outside time; and of the Virgin Mary, without a father, in time." },
    { c: 3, n: 106, q: "What does Scripture say about the Annunciation?", a: "The angel Gabriel is sent to Nazareth, to a virgin named Mary, betrothed to Joseph: “Hail, thou that art highly favoured, the Lord is with thee… thou shalt bring forth a son, and shalt call his name Jesus.” To her question — “How shall this be?” — the angel replies: “The Holy Spirit shall come upon thee, and the power of the Highest shall overshadow thee.” Mary answers: “Behold the handmaid of the Lord; be it unto me according to thy word” (Luke 1:26-38)." },
    { c: 3, n: 107, q: "Who was the Virgin Mary?", a: "A daughter of the line of Abraham and David, from which the Messiah was to be born. Dedicated to God from childhood, she had promised to remain a virgin; Joseph was betrothed to her to be the guardian of her purity." },
    { c: 3, n: 108, q: "Why is she called “Ever-Virgin”?", a: "Because she remained a virgin before, during and after the birth of Christ. The three stars painted on her veil, on her forehead and shoulders, in icons, recall this." },
    { c: 3, n: 109, q: "Why is Mary called “Theotokos”?", a: "The Greek word means “she who gave birth to God”. It fulfils Isaiah’s prophecy taken up by St Matthew: “A virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us” (Matt 1:23). Elizabeth already calls her “the mother of my Lord” (Luke 1:43)." },
    { c: 3, n: 110, q: "In what sense is Mary “Mother of God” (Theotokos)?", a: "She did not give Christ his divinity, but the one she conceived and bore according to the flesh was from his conception true God, the second Person of the Trinity. That is why she is truly the Mother of God." },
    { c: 3, n: 111, q: "What was the birth of Christ like?", a: "According to Tradition, it was a holy birth without corruption, which the Mother of God went through without the pains of childbirth foretold to Eve (Gen 3:16)." },
    { c: 3, n: 112, q: "How could the Messiah be recognised?", a: "Through the Scriptures: “They are they which testify of me” (John 5:39). The Old Testament contains hundreds of prophecies fulfilled in Jesus: born of a virgin (Isa 7:14), descended from Abraham and David, born in Bethlehem (Mic 5:2), preceded by a messenger (Mal 3:1), entering Jerusalem on a colt (Zech 9:9), sold for thirty pieces of silver (Zech 11:12), his hands and feet pierced (Ps 22:16), lots cast for his clothing (Ps 22:18)…" },
    { c: 3, n: 113, q: "Did people at the time know that the Messiah had been born?", a: "Yes: the Magi recognised him by the star, the shepherds learned of it from the angels, the elder Simeon and the prophetess Anna recognised him in the Temple, inspired by the Spirit." },
    { c: 3, n: 114, q: "What miracles did Christ perform?", a: "He healed incurable diseases and freed the possessed, sometimes at a distance or by a simple touch; he multiplied the loaves, walked on the water, calmed the storm; he raised the son of the widow of Nain, the daughter of Jairus, and Lazarus, four days dead. “If they should be written every one, I suppose that even the world itself could not contain the books” (John 21:25)." },
    { c: 3, n: 115, q: "How did Christ accomplish our salvation?", a: "Through his whole life: his incarnation, his teaching, his earthly life, his death, his resurrection and his ascension. Each of these stages heals and raises up a part of our humanity." },
    { c: 3, n: 116, q: "How does the Incarnation save us?", a: "By uniting in himself the divine nature and the human nature, Christ healed from within the wounded humanity of Adam. What has been united to God is saved." },
    { c: 3, n: 117, q: "How does Christ save us through his teaching?", a: "Through the Gospel of the Kingdom, which the Church proclaims without alteration. It becomes a path of salvation when we welcome it with all our heart and put it into practice." },
    { c: 3, n: 118, q: "How does his life save us?", a: "By giving us a model to imitate: acquiring the feelings, the will and the Spirit of Christ, directly or by following the example of his saints. “Be ye followers of me, even as I also am of Christ” (1 Cor 11:1)." },
    { c: 3, n: 119, q: "How does Christ save us through his death?", a: "Through death he destroyed “him that had the power of death, that is, the devil” (Heb 2:14). We receive this salvation by entering the Church through baptism, in which we die and rise with him (Rom 6:3-4), and by receiving his Body and Blood." },
    { c: 3, n: 120, q: "How does Christ save us through his resurrection?", a: "By breaking the gates of Hades and freeing the righteous, he conquered death and opened paradise to all who repent — the good thief entered it first (Luke 23:43). Thanks to his resurrection, all people will rise on the last day." },
    { c: 3, n: 121, q: "How does Christ save us through his ascension?", a: "By raising our human nature above all the heavens, to the right hand of the Father, he opens to us the possibility of becoming “partakers of the divine nature” (2 Pet 1:4)." },
    { c: 3, n: 122, q: "Why say both “was incarnate” and “became man”?", a: "The Fathers of Nicaea added “became man” to stress that the Son took not merely flesh, but the whole of human nature — body, soul and spirit — becoming perfect man." },
    { c: 4, n: 123, q: "Why was Christ crucified?", a: "He humbled himself voluntarily, “obedient unto death, even the death of the cross” (Phil 2:8), to snatch each person from death and purify our nature. “The Son of man came… to minister, and to give his life a ransom for many” (Mark 10:45)." },
    { c: 4, n: 124, q: "Why did Christ die on a cross?", a: "To take upon himself the curse that weighed on us: “Christ hath redeemed us from the curse… for it is written, Cursed is every one that hangeth on a tree” (Gal 3:13). The Fathers love to contemplate it point by point: his hands are pierced to heal Adam’s hands stretched out to the fruit, his feet to heal those that went to hide; he wears a crown of thorns to lift the curse of the ground that “shall bring forth thorns”; his side is opened to heal the rib from which Eve was taken." },
    { c: 4, n: 125, q: "What does “redemption” or “ransom” mean?", a: "In the past, a ransom was the price paid to free a slave or a captive. Christ gave his own life to free us from slavery to sin, death and the devil." },
    { c: 4, n: 126, q: "Why does John the Baptist call Jesus “the Lamb of God”?", a: "Because Christ took upon himself the weight of our sins. On the cross he is both the victim offered according to his humanity, like a lamb, and the High Priest who offers the sacrifice according to his divinity. The Liturgy sings it: “Thou art the One who offers and is offered”." },
    { c: 4, n: 127, q: "Why does the Creed mention Pontius Pilate?", a: "To anchor our faith in real history: God acts in our time. Christ died under a known Roman governor — this is not a timeless myth." },
    { c: 4, n: 128, q: "How could Christ suffer and die if he is God?", a: "He suffered and died in his humanity, truly and not in appearance. He could have escaped suffering, but he freely accepted it: “No man taketh it from me, but I lay it down of myself” (John 10:18)." },
    { c: 4, n: 129, q: "How does Christ’s death differ from ours?", a: "For us, death is the consequence of sin. He, being sinless, was not bound to die: he tasted a death that was not his due, laden with the weight of our faults. And because Life itself entered into it, death was conquered from within." },
    { c: 4, n: 130, q: "What are the seven words of Christ on the cross?", a: "“Father, forgive them” (Luke 23:34); “To day shalt thou be with me in paradise” (Luke 23:43); “Woman, behold thy son… Behold thy mother” (John 19:26-27); “My God, my God, why hast thou forsaken me?” (Matt 27:46); “I thirst” (John 19:28); “It is finished” (John 19:30); “Father, into thy hands I commend my spirit” (Luke 23:46)." },
    { c: 4, n: 131, q: "How was Christ buried?", a: "Joseph of Arimathea, a secret disciple, obtained the body of Jesus from Pilate; Nicodemus brought myrrh and aloes. They wrapped him in linen cloths with the spices and laid him in a new tomb hewn out of the rock, in a garden near Golgotha (John 19:38-42). The Church sings of this burial on Great Friday, around the <em>Epitaphios</em>." },
    { c: 4, n: 132, q: "Where was Christ between his death and his resurrection?", a: "His body lay in the tomb, and his soul, still united to his divinity, descended into Hades to free the righteous of the Old Testament. This is what the icon of the Resurrection shows, where Christ raises up Adam and Eve." },
    { c: 4, n: 133, q: "Did Christ suffer for all people?", a: "Yes, for all, without exception. But for this salvation to bear fruit, each person must freely take part in it, “being made conformable unto his death” (Phil 3:10) — through faith, the sacraments and spiritual struggle." },
    { c: 4, n: 134, q: "How can we share in Christ’s death?", a: "Through sincere faith; through the sacraments, which contain the power of his Passion; and by “crucifying the flesh with its affections and lusts” (Gal 5:24), that is, by struggling against whatever enslaves us." },
    { c: 4, n: 135, q: "In practice, how do we fight the passions?", a: "By practising the opposite virtue, in imitation of Christ and the saints: if anger rises in us, remember Christ praying for his executioners; set humility against pride; set sharing against greed." },
    { c: 5, n: 136, q: "What does the article “On the third day he rose again” teach us?", a: "That Christ truly rose, as the prophets and the psalms foretold, and that he rose in his own body, the very one born of the Virgin and crucified." },
    { c: 5, n: 137, q: "What is the link between Christ’s resurrection and us?", a: "It is the foundation of our own resurrection: “Now is Christ risen from the dead, and become the firstfruits of them that slept” (1 Cor 15:20). Each person will rise in his or her own body." },
    { c: 5, n: 138, q: "What are the signs of Christ’s resurrection?", a: "The empty tomb; the grave clothes left in place; the appearances to the myrrh-bearing women, to the Apostles, to more than five hundred brethren at once (1 Cor 15:6); the transformation of frightened disciples into witnesses ready to die; and, to this day, the living experience of the Church." },
    { c: 5, n: 139, q: "Where do the words “according to the Scriptures” come from?", a: "From St Paul: “I delivered unto you first of all that which I also received, how that Christ died for our sins according to the scriptures; and that he was buried, and that he rose again the third day according to the scriptures” (1 Cor 15:3-4)." },
    { c: 5, n: 140, q: "What does “according to the Scriptures” mean?", a: "That the death and resurrection of Christ fulfil what the Old Testament foretold. The words are taken from St Paul (1 Cor 15:3-4)." },
    { c: 5, n: 141, q: "Where did the Old Testament foretell it?", a: "Isaiah: “He was wounded for our transgressions… and with his stripes we are healed” (Isa 53:5). Psalm 16: “Neither wilt thou suffer thine Holy One to see corruption.” And the sign of Jonah, three days in the belly of the fish (Matt 12:40)." },
    { c: 6, n: 142, q: "How did the Ascension take place?", a: "Forty days after Pascha, on the Mount of Olives, Christ was taken up before the Apostles’ eyes and a cloud received him out of their sight. Two angels said to them: “This same Jesus… shall so come in like manner as ye have seen him go into heaven” (Acts 1:11)." },
    { c: 6, n: 143, q: "Was the Ascension foretold?", a: "Yes. The prophet Zechariah announced: “His feet shall stand in that day upon the mount of Olives, which is before Jerusalem on the east” (Zech 14:4) — the very place of the Ascension." },
    { c: 6, n: 144, q: "Did Christ ascend into heaven as man or as God?", a: "As man, with the body he had received from the Virgin. As God, he never left heaven, since he is present everywhere." },
    { c: 6, n: 145, q: "Does God the Father have a “right hand side”?", a: "No, it is an image. “Sitting at the right hand of the Father” means that Christ, in his humanity, receives the same glory and power as the Father — which he already possessed from all eternity according to his divinity." },
    { c: 6, n: 146, q: "Where does the image of “sitting at the right hand” come from?", a: "From royal ceremonial: to sit at the king’s right hand meant to share fully in his honour and power. Thus King Solomon had his mother sit at his right hand (1 Kgs 2:19)." },
    { c: 6, n: 147, q: "What does Christ do after the Ascension?", a: "He intercedes for us before the Father as Mediator and High Priest (Heb 7:25); he governs his Church, of which he is the Head; he sends the Holy Spirit; he prepares a place for us." },
    { c: 6, n: 148, q: "What is the role of the Ascension in our salvation?", a: "Christ raises our human nature into the heart of God and opens the way to heaven for us: “In my Father’s house are many mansions… I go to prepare a place for you” (John 14:2)." },
    { c: 7, n: 149, q: "How will Christ come again?", a: "In the same way as he ascended into heaven: “This same Jesus… shall so come in like manner as ye have seen him go into heaven” (Acts 1:11) — visibly, in glory." },
    { c: 7, n: 150, q: "What does Christ say about the Last Judgement?", a: "“The hour is coming, in the which all that are in the graves shall hear his voice, and shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation” (John 5:28-29). The Father has committed judgement to the Son, “because he is the Son of man”." },
    { c: 7, n: 151, q: "What is the difference between Christ’s first and second coming?", a: "The first time, he came humbly, in the form of a servant, to suffer for us; the second time, he will come in his glory, with all his angels, to judge. The first time few recognised him; the second time he will be visible to all, “as the lightning”." },
    { c: 7, n: 152, q: "Will Christ judge everyone?", a: "Yes, all people, without exception." },
    { c: 7, n: 153, q: "How will Christ judge us?", a: "Each person’s conscience will be brought fully into the light: not only deeds, but words, thoughts and the intentions of the heart (1 Cor 4:5). The one who judges is the one who gave his life for us." },
    { c: 7, n: 154, q: "Shall we be judged for all our deeds?", a: "For everything from which we have not been cleansed by repentance and the conversion of our life. That is why the Church urges us not to put off confession." },
    { c: 7, n: 155, q: "When will the Last Judgement take place?", a: "No one knows: “Watch therefore, for ye know neither the day nor the hour” (Matt 25:13). We must be ready at every moment to meet Christ." },
    { c: 7, n: 156, q: "Are there signs of the second coming?", a: "Christ foretold some: the Gospel preached to all nations, the cooling of faith and love, the multiplying of wars and calamities, the coming of the Antichrist (Matt 24). But he warns against those who claim to fix dates." },
    { c: 7, n: 157, q: "Who is the Antichrist?", a: "An adversary of Christ who is to appear at the end of time, and “whom the Lord shall consume with the spirit of his mouth, and shall destroy with the brightness of his coming” (2 Thess 2:8). The Church calls for vigilance rather than fear." },
    { c: 7, n: 158, q: "What does Scripture say about Christ’s eternal reign?", a: "The angel announces it to Mary: “The Lord God shall give unto him the throne of his father David: and he shall reign… for ever; and of his kingdom there shall be no end” (Luke 1:32-33)." },
    { c: 7, n: 159, q: "What is the Kingdom of God?", a: "The Fathers distinguish three senses: the Kingdom of nature (God, King of all creation); the Kingdom of grace (the Church on earth); the Kingdom of glory (the saints in heaven). It is the last that “shall have no end”." },
    { c: 7, n: 160, q: "Which Kingdom “shall have no end”?", a: "The Kingdom of glory, which will begin in its fullness at Christ’s second coming." },
    { c: 7, n: 161, q: "Will the joy of the righteous and the pain of sinners be eternal?", a: "Christ affirms it: “These shall go away into everlasting punishment: but the righteous into life eternal” (Matt 25:46). These grave words are a call to conversion while there is still time, not a threat meant to frighten." },
    { c: 7, n: 162, q: "Will it still be possible to repent after the Judgement?", a: "No: the time for conversion is this life. After the Judgement there will be no more time, and each person will enter eternity according to the state of his or her soul. Hence the urgency of God’s “today”." },
    { c: 7, n: 163, q: "What becomes of the soul after death?", a: "It enters the invisible world, conscious and sensitive, and undergoes a particular judgement. It awaits the resurrection and the Last Judgement, in a foretaste of joy or of pain. That is why the Church prays for the departed, especially on the 3rd, 9th and 40th days." },
    { c: 7, n: 164, q: "Does purgatory exist?", a: "The Orthodox Church does not hold the teaching on purgatory as it was defined in the West in the 15th century, with the idea of an expiatory penalty to be “paid”. She does believe, with the whole Tradition, that the prayer of the Church, the Liturgy and almsgiving help the departed." },
    { c: 8, n: 165, q: "Who is the Holy Spirit?", a: "The third Person of the Trinity, of the same nature as the Father and the Son, distinguished by his personal property: he proceeds from the Father." },
    { c: 8, n: 166, q: "Where does Scripture call the Spirit “God”?", a: "St Peter says to Ananias: “Why hath Satan filled thine heart to lie to the Holy Spirit?… Thou hast not lied unto men, but unto God” (Acts 5:3-4). St Paul calls our body both “the temple of God” and “the temple of the Holy Spirit” (1 Cor 3:16; 6:19)." },
    { c: 8, n: 167, q: "What does “the Giver of Life” mean?", a: "The Spirit has divine attributes: he takes part in creation (Gen 1:2), he knows all things, he is present everywhere, he gives people birth into spiritual life (John 3:5), he sanctifies and gives eternal life." },
    { c: 8, n: 168, q: "What does “who proceeds from the Father” mean?", a: "That the Father is the sole source of the Spirit, as he is of the Son. These are Christ’s own words: “the Spirit of truth, which proceedeth from the Father” (John 15:26)." },
    { c: 8, n: 169, q: "Does the Spirit also proceed from the Son (Filioque)?", a: "No, according to the Orthodox faith: the Father is the sole cause in the Trinity. The Filioque (“and the Son”) was added to the Creed later in the West, although the Council of Ephesus (431) had forbidden any change to the Symbol. The Spirit is, however, sent into the world by the Son, and rests upon him." },
    { c: 8, n: 170, q: "Who bears witness that the Spirit proceeds from the Father alone?", a: "The Council of Ephesus (431), which forbade any change to the Symbol, and the unanimity of the Fathers. St Gregory of Nazianzus: “All that the Father has, the Son has, except being cause.” St John of Damascus: “We say that the Spirit is from the Father… we do not say that he is from the Son, but we call him the Spirit of the Son.”" },
    { c: 8, n: 171, q: "Is the Holy Spirit worshipped like the Father and the Son?", a: "Yes, with one and the same worship, for he is equal to them: we are baptised “in the name of the Father, and of the Son, and of the Holy Spirit” (Matt 28:19), and we sing “Glory to the Father, and to the Son, and to the Holy Spirit”." },
    { c: 8, n: 172, q: "Why “who spoke by the prophets”?", a: "To affirm, against certain false teachers, that the Old Testament is inspired by the same Spirit: “Holy men of God spake as they were moved by the Holy Spirit” (2 Pet 1:21)." },
    { c: 8, n: 173, q: "Why doesn’t the Creed say the Spirit spoke through the Apostles?", a: "Because at that time nobody doubted that the Holy Spirit had spoken through the Apostles. The clarification was needed only for the prophets of the Old Testament." },
    { c: 8, n: 174, q: "How did the Spirit reveal himself to people?", a: "He came down upon the Apostles in the form of tongues of fire on the fiftieth day after Pascha, at Pentecost (Acts 2)." },
    { c: 8, n: 175, q: "Is the Spirit still given today?", a: "Yes, to all believers: through prayer, through the practice of the virtues, and above all through the sacraments of the Church. “The goal of the Christian life is the acquisition of the Holy Spirit,” said St Seraphim of Sarov." },
    { c: 8, n: 176, q: "What are the gifts of the Spirit?", a: "The prophet Isaiah lists seven: the spirit of wisdom and understanding, of counsel and might, of knowledge and godliness, and of the fear of the Lord (Isa 11:2)." },
    { c: 8, n: 177, q: "How can one know whether one has received the grace of the Spirit?", a: "By its fruits: “love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, temperance” (Gal 5:22-23). Not by extraordinary phenomena." },
    { c: 9, n: 178, q: "What is the Church?", a: "The community established by God, gathering those who are united by the Orthodox faith, the commandments of God, the apostolic hierarchy and the sacraments." },
    { c: 9, n: 179, q: "Where does the word “Church” come from?", a: "From the Greek <em>ekklesia</em>, “assembly of those who are called”. In ancient Athens it was the assembly of citizens summoned together; the Church is the assembly of those whom God calls and who answer his call." },
    { c: 9, n: 180, q: "How can we “believe” in the Church, since she is visible?", a: "Just as Christ has a visible human nature and an invisible divine nature, the Church has a visible aspect — her members, her bishops, her places of worship — and an invisible aspect: the grace of the Spirit at work in her. It is in this that we believe." },
    { c: 9, n: 181, q: "What does “believing in the Church” mean?", a: "It means honouring her as the true Church of Christ, following her teaching and commandments, with the certainty that God’s grace lives and works in her, flowing from her one Head, Christ (Col 1:18)." },
    { c: 9, n: 182, q: "Which image of the Church does Scripture use most?", a: "That of the body and the head: the Church is the Body of Christ, of which he is the Head and we are the members (1 Cor 12:27; Col 1:18). A divine-human organism." },
    { c: 9, n: 183, q: "Who belongs to the Church?", a: "Orthodox Christians living on earth, all who have died in the true faith and in repentance, and the angels. The Church on earth and the Church in heaven form one single Church." },
    { c: 9, n: 184, q: "Is the Church both on earth and in heaven?", a: "Yes: one Church in two “flocks”. On earth, the Church “militant”, on the way to the homeland (Heb 13:14); in heaven, the Church “triumphant”, that of the angels and saints, who have already reached the goal (Heb 12:22-23)." },
    { c: 9, n: 185, q: "How was the Church founded?", a: "Promised by Christ (“I will build my Church”, Matt 16:18), purchased with his blood on the cross, she was born at Pentecost, when the Spirit came down upon the Apostles." },
    { c: 9, n: 186, q: "What are “the gates of hell”?", a: "In ancient cities, power sat at the city gates. “The gates of hell” therefore mean the whole power of the Evil One." },
    { c: 9, n: 187, q: "“The gates of hell shall not prevail against it”: what does this mean?", a: "That the Church will always exist, from Pentecost to Christ’s second coming, despite all persecutions: “I am with you always, even unto the end of the world” (Matt 28:20)." },
    { c: 9, n: 188, q: "Can the Church be destroyed?", a: "No. Christ is the “strong man” who guards his house (Matt 12:29), and he remains with her every day (Matt 28:20). Communities may disappear; the Church of Christ remains." },
    { c: 9, n: 189, q: "Can the Church be hidden?", a: "No: she remains always accessible to those who seek God. “Neither do men light a candle, and put it under a bushel” (Matt 5:15)." },
    { c: 9, n: 190, q: "Is the Church on earth visible?", a: "Yes. She could be persecuted precisely because she was visible (Acts 8:1). Christ himself says: “If he shall neglect to hear them, tell it unto the church” (Matt 18:17) — which presupposes a concrete Church to which one can turn." },
    { c: 9, n: 191, q: "On whom is the Church founded?", a: "On Christ, the one cornerstone. The “rock” of which Jesus speaks to Peter (Matt 16:18) is, according to many Fathers, the faith Peter had just confessed on behalf of all the Apostles: “Thou art the Christ, the Son of the living God”." },
    { c: 9, n: 192, q: "Did the Apostle Peter have primacy?", a: "A primacy of honour, together with St Paul: he was “first among equals”, often the Apostles’ spokesman. But he did not command the others: at the Council of Jerusalem it was James who presided and drew the conclusion (Acts 15)." },
    { c: 9, n: 193, q: "Did Peter have authority over the other Apostles?", a: "No, according to the Orthodox tradition, despite his great authority. He did not give orders to the other Apostles; at the Council of Jerusalem James presided (Acts 15); Paul rebuked him publicly (Gal 2:11); the Apostles sent him on mission to Samaria (Acts 8:14); and he called himself “an elder among the elders” (1 Pet 5:1). The keys of the Kingdom were entrusted to all the Apostles (Matt 18:18)." },
    { c: 9, n: 194, q: "Does Peter’s authority pass to the bishops of Rome alone?", a: "No. Peter founded several Churches, including Antioch, without their bishops claiming any special inheritance. Every Orthodox bishop is a successor of the Apostles in the power to bind and loose, to baptise and to teach (St Nilus Cabasilas)." },
    { c: 9, n: 195, q: "Does the bishop of Rome have authority over the whole Church?", a: "Not according to the Orthodox tradition, which recognises that Rome held a primacy of honour in the first millennium, but not a power of universal jurisdiction. St Cyprian taught that “the Church rests on the bishops”; Pope St Gregory the Great himself refused the title of “universal bishop”; and it was the ecumenical councils, not a single bishop, that settled questions of faith." },
    { c: 9, n: 196, q: "How many were the first Christians?", a: "At Peter’s first preaching, three thousand people were baptised (Acts 2:41), then five thousand (Acts 4:4); “and the Lord added to the church daily such as should be saved” (Acts 2:47)." },
    { c: 9, n: 197, q: "Why is the Church “one”?", a: "Because she is the one Body of Christ, animated by the one Spirit: “one body, and one Spirit… one Lord, one faith, one baptism, one God and Father of all” (Eph 4:4-6)." },
    { c: 9, n: 198, q: "What does the unity of the Church imply for us?", a: "To “keep the unity of the Spirit in the bond of peace” (Eph 4:3) and to beware of those who cause divisions and offences (Rom 16:17)." },
    { c: 9, n: 199, q: "What is the link between the universal Church and the local Churches?", a: "The one Church of Christ exists today in the form of some fifteen autocephalous Churches — Constantinople, Alexandria, Antioch, Jerusalem, Russia, Serbia, Romania, Bulgaria, Georgia, Greece and others — united in the same faith, the same sacraments and the same apostolic succession." },
    { c: 9, n: 200, q: "How is the unity of the Church shown?", a: "In the unity of faith (the same Creed), of the sacraments and liturgy, of the apostolic succession of bishops, and of the canons that order the life of the Church." },
    { c: 9, n: 201, q: "Are the Church on earth and the Church in heaven united?", a: "Yes: they have one Head, Christ, and live in communion with each other." },
    { c: 9, n: 202, q: "How does the Church on earth communicate with the Church in heaven?", a: "Through prayer: we pray to God, and we ask the saints to pray with us and for us." },
    { c: 9, n: 203, q: "What is prayer to the saints based on?", a: "On Tradition, whose roots are found in Scripture: David prays to “the Lord God of Abraham, Isaac, and of Israel, our fathers” (1 Chr 29:18). St Cyril of Jerusalem explains that we commemorate the patriarchs, prophets, apostles and martyrs “so that God may receive our prayer through their intercession”." },
    { c: 9, n: 204, q: "Does Scripture speak of the prayer of the saints?", a: "Yes. In Revelation, St John sees an angel offering incense on the golden altar “with the prayers of all saints” (Rev 8:3-4). And “the effectual fervent prayer of a righteous man availeth much” (Jas 5:16)." },
    { c: 9, n: 205, q: "Does God work miracles through the saints?", a: "Yes, and even through their relics: a dead man came back to life on touching the bones of the prophet Elisha (2 Kgs 13:21); cloths that had touched St Paul healed the sick (Acts 19:12). This is the basis of the veneration of relics." },
    { c: 9, n: 206, q: "Should we pray for the departed?", a: "Yes, it is a duty of love: the departed can no longer act for themselves, but they count on our prayers, our alms and above all the Liturgy offered for them. Judas Maccabeus already had a sacrifice offered for the dead (2 Macc 12:43-45)." },
    { c: 9, n: 211, q: "Why is the Church “apostolic”?", a: "Because she keeps and hands on unaltered the faith of the Apostles, “once delivered unto the saints” (Jude 3), and because she preserves the unbroken succession of ordinations from the Apostles." },
    { c: 9, n: 212, q: "What is Holy Tradition?", a: "From the Latin <em>tradere</em>, “to hand on”. It is the living transmission, oral and written, from generation to generation, of the faith, the commandments, the liturgy and the spiritual experience of the Church. Holy Scripture is at its heart." },
    { c: 9, n: 213, q: "How is Holy Tradition handed on?", a: "In the Church, since the Apostles: the Church is “the pillar and ground of the truth” (1 Tim 3:15)." },
    { c: 9, n: 214, q: "Does Scripture speak of Tradition?", a: "Yes: “Hold the traditions which ye have been taught, whether by word, or our epistle” (2 Thess 2:15). The Church is “the pillar and ground of the truth” (1 Tim 3:15)." },
    { c: 9, n: 215, q: "Did the Apostles use an oral tradition?", a: "Yes. St Paul cites elements of Jewish oral tradition not found in the Old Testament: the names of Pharaoh’s magicians, Jannes and Jambres (2 Tim 3:8), or the successive “heavens” (2 Cor 12:2); St Jude mentions the archangel Michael’s dispute with the devil over the body of Moses (Jude 9). Scripture itself was born within a living tradition." },
    { c: 9, n: 216, q: "Why so many Christian confessions with one Bible?", a: "Because the Bible does not interpret itself. The Ethiopian eunuch said so to Philip: “How can I, except some man should guide me?” (Acts 8:31). Cut off from Tradition, the Bible gives rise to contradictory readings." },
    { c: 9, n: 217, q: "Can the meaning of the Bible be distorted?", a: "Yes. St Peter already warns about Paul’s letters: “In which are some things hard to be understood, which they that are unlearned and unstable wrest, as they do also the other scriptures, unto their own destruction” (2 Pet 3:16)." },
    { c: 9, n: 218, q: "How should the Bible be interpreted?", a: "In the Church, with the Spirit who inspired it, and in the light of the holy Fathers. “No prophecy of the scripture is of any private interpretation” (2 Pet 1:20)." },
    { c: 9, n: 219, q: "Which Fathers of the Church are authoritative?", a: "In every age the Church raises up saints who interpret Scripture faithfully. The Fifth Council (553), for example, names St Athanasius of Alexandria, St Hilary of Poitiers, St Basil the Great, St Gregory the Theologian, St Ambrose of Milan, St Augustine, St John Chrysostom, St Cyril of Alexandria and St Leo the Great." },
    { c: 9, n: 220, q: "What does “consensus of the Fathers” mean?", a: "The agreement of the holy Fathers. St Vincent of Lérins (5th century) gave its rule: to hold as true “what has been believed everywhere, always and by all”." },
    { c: 9, n: 221, q: "How was the canon of the Bible formed?", a: "Gradually, through councils and the writings of the Fathers (Melito of Sardis, Irenaeus of Lyons, Athanasius of Alexandria, the Council of Laodicea). The councils of Carthage (end of the 4th century) drew up the list, which the Council in Trullo (692) made binding on the whole Church. The catechism counts 39 books for the Old Testament and 27 for the New; the Orthodox Church also reads, as useful for edification, the deuterocanonical books of the Septuagint (Wisdom, Sirach, Tobit, Maccabees…)." },
    { c: 9, n: 222, q: "How can we recognise that the Bible is inspired by God?", a: "The catechism proposes five criteria: 1. it reveals what man could not have worked out alone (creation out of nothing, the Trinity, the Incarnation); 2. the height of its moral teaching (loving one’s enemies, laying down one’s life); 3. fulfilled prophecies; 4. the miracles that accompany it; 5. its power to transform the human heart across the centuries." },
    { c: 9, n: 223, q: "What else does the Church keep from the Apostles?", a: "Together with apostolic Tradition, she preserves the unbroken succession of ordinations from the Apostles." },
    { c: 9, n: 224, q: "How is ministry organised in the Church?", a: "In three orders established in apostolic times: deacons (Acts 6), priests or presbyters (Acts 14:23) and bishops (1 Tim 3)." },
    { c: 9, n: 225, q: "What is apostolic succession?", a: "The unbroken chain of the laying-on of hands, from the Apostles to the bishops and from bishop to bishop down to our day, through which the ministry and the gifts of the Spirit are handed on. In the Russian Church, the patriarch is thus the successor, in an unbroken line, of the Apostle Andrew." },
    { c: 9, n: 226, q: "What does Scripture say about apostolic succession?", a: "That the gift of priesthood is handed on by the laying-on of hands: “Stir up the gift of God, which is in thee by the putting on of my hands” (2 Tim 1:6); “For this cause left I thee in Crete… to ordain elders in every city” (Titus 1:5). According to the apostolic canons, a bishop is ordained by two or three bishops, a priest or deacon by one bishop." },
    { c: 9, n: 227, q: "An example of apostolic succession today?", a: "For the Russian Church, the list of bishops goes back without interruption to the Apostle Andrew, “the First-Called”; the book gives the complete list in an appendix." },
    { c: 9, n: 228, q: "What authority can speak on behalf of the whole Church?", a: "The ecumenical council, which gathers the bishops of all the local Churches: it is the supreme authority in the Church." },
    { c: 9, n: 229, q: "Who is the patriarch?", a: "The first bishop, “first among equals”, of a local Church. He presides over the council of his Church and represents it before the other Churches, deciding nothing without the agreement of his brother bishops (34th Apostolic Canon)." },
    { c: 9, n: 230, q: "What is the link between the “one, holy, catholic and apostolic Church” and the Orthodox Church?", a: "The Orthodox Church recognises herself as that very Church. The word “Orthodox” — right belief, right glory — came into use in the first centuries to distinguish her from groups that had separated from her." },
    { c: 9, n: 231, q: "Can one be saved outside the Orthodox Church?", a: "The catechism recalls the traditional teaching: Christ is “the head of the church: and he is the saviour of the body” (Eph 5:23); salvation is life in this Body, and the Orthodox Church recognises herself as that Church. Yet she does not pronounce on the fate of each person, which belongs to God alone, and believes that God’s grace calls all people (see Q 238)." },
    { c: 10, n: 232, q: "Why does the Creed speak of Baptism?", a: "Because faith is confirmed and sealed by Baptism and by the other Mysteries of the Church." },
    { c: 10, n: 233, q: "What is a sacrament, or Mystery?", a: "A sacred act through which God acts upon man with his invisible grace, directly or through visible matter (Greek <em>mysterion</em>)." },
    { c: 10, n: 234, q: "How many sacraments are there?", a: "In the broad sense, God’s grace has no limits. In the ecclesial sense, seven are counted: Baptism, Chrismation, the Eucharist, Confession, Ordination, Marriage and the Anointing of the sick." },
    { c: 10, n: 235, q: "Through what matter does God act in the sacraments?", a: "Water for Baptism; oil for Chrismation and Anointing; bread and wine, which become the Body and Blood of Christ, for the Eucharist; the laying-on of hands for Ordination; the word of absolution for Confession; the mutual consent and the crowns for Marriage." },
    { c: 10, n: 236, q: "What does each sacrament give?", a: "Baptism gives birth to spiritual life; Chrismation gives the strength of the Spirit; the Eucharist nourishes for eternal life; Confession heals and forgives; Marriage sanctifies the union of husband and wife; Ordination gives the Church her shepherds; Anointing comforts and heals the sick." },
    { c: 10, n: 237, q: "Who performs the sacraments?", a: "God himself, truly, through the ministry of bishops and priests. “The one who baptises is neither Peter nor Ambrose: we carry out our service, but the effect comes from the Holy Spirit” (St Ambrose of Milan)." },
    { c: 10, n: 238, q: "Does God’s grace act outside the Orthodox Church?", a: "The Fathers, and the Encyclical of the Eastern Patriarchs (1723), distinguish two actions of the one divine grace. The grace <strong>that calls</strong> acts on all people of every nation and confession — God “will have all men to be saved” and “lighteth every man” (John 1:9) — to lead them towards his Church. The grace <strong>that saves</strong>, given through the sacraments, is the one the Orthodox Church is conscious of bearing in its fullness." },
    { c: 10, n: 239, q: "Why does the Creed mention only Baptism?", a: "Because of the debates of the time about whether those returning from schism or heresy should be rebaptised. The Church confesses one baptism (Eph 4:5) and does not repeat a baptism properly given in the name of the Trinity." },
    { c: 10, n: 240, q: "What happens at Baptism?", a: "The believer is immersed three times in water, in the name of the Father, and of the Son, and of the Holy Spirit: he dies to the life of sin and rises to a new and holy life." },
    { c: 10, n: 241, q: "What does dying and rising in Baptism mean?", a: "“We were baptised into his death” (Rom 6:3). The immersion signifies Christ’s death, the three immersions his three days in the tomb, the coming up out of the water his resurrection. The baptised “puts on Christ” (Gal 3:27)." },
    { c: 10, n: 242, q: "Is Baptism necessary for salvation?", a: "Christ says so: “Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God” (John 3:5). As an egg must hatch, the one born of the flesh must be born of the Spirit. God alone, however, judges those who were unable to receive it." },
    { c: 10, n: 243, q: "Where does Baptism come from?", a: "It was prefigured by John’s baptism of repentance in the Jordan, which Christ sanctified by receiving it. After his resurrection, Christ commanded the Apostles: “Teach all nations, baptising them in the name of the Father, and of the Son, and of the Holy Spirit” (Matt 28:19)." },
    { c: 10, n: 244, q: "Can one baptise by sprinkling?", a: "Baptism is normally performed by threefold complete immersion. Sprinkling is admitted only in extreme cases, such as danger of death." },
    { c: 10, n: 245, q: "Who can baptise?", a: "Normally a bishop or a priest. In an emergency (danger of death), any Orthodox Christian may baptise by immersing three times in water, or by pouring water, with the words: “The servant of God N. is baptised in the name of the Father, amen; and of the Son, amen; and of the Holy Spirit, amen.”" },
    { c: 10, n: 246, q: "What is essential in the rite of Baptism?", a: "The threefold immersion accompanied by the words: “The servant of God N. is baptised in the name of the Father, amen; and of the Son, amen; and of the Holy Spirit, amen.”" },
    { c: 10, n: 247, q: "What is required to be baptised?", a: "Faith and repentance: “Repent, and be baptised every one of you in the name of Jesus Christ” (Acts 2:38). Hence the time of the catechumenate for adults." },
    { c: 10, n: 248, q: "Should little children be baptised?", a: "Yes. The Church has baptised children since the Apostles, who baptised “whole households” (Acts 16:15, 33). Grace acts in the child’s soul beyond what the child understands, as John the Baptist leapt in his mother’s womb (Luke 1:41)." },
    { c: 10, n: 249, q: "Are unbaptised children without sin?", a: "They have committed no personal fault, but, like every human being, they are born with a nature wounded by original sin, which needs healing; that is why the Church baptises little children (St Paul distinguishes the child consecrated to God from the one who is not, 1 Cor 7:14). The Church entrusts children who die unbaptised to the mercy of God." },
    { c: 10, n: 250, q: "Why does God want children to belong to his people?", a: "Under the Old Covenant, boys were circumcised on the eighth day and so entered the chosen people (Gen 17:12). Baptism fulfils this figure. Christ came to make access to God easier, not harder: “Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven” (Matt 19:14)." },
    { c: 10, n: 251, q: "Where do we see that circumcision foreshadowed Baptism?", a: "In St Paul: “In whom also ye are circumcised with the circumcision made without hands… buried with him in baptism, wherein also ye are risen with him” (Col 2:11-12)." },
    { c: 10, n: 252, q: "Does the promise of Baptism also concern children?", a: "Yes: “Ye shall receive the gift of the Holy Spirit. For the promise is unto you, and to your children, and to all that are afar off” (Acts 2:38-39)." },
    { c: 10, n: 253, q: "Can a little child receive the grace of the Spirit?", a: "Yes, even if the child’s reason is not yet developed: John the Baptist, “filled with the Holy Spirit, even from his mother’s womb”, leaps at Mary’s approach (Luke 1:15, 41); the little ones acclaim Christ in Jerusalem (Matt 21:16); God says to Jeremiah: “Before thou camest forth out of the womb I sanctified thee” (Jer 1:5)." },
    { c: 10, n: 254, q: "Who confesses the faith for a child at baptism?", a: "The godparents, together with the parents. They undertake to raise the child in the Orthodox faith. For grace can be given to some through the faith of others: the paralytic was forgiven because of the faith of those who carried him (Mark 2:5)." },
    { c: 10, n: 255, q: "Can grace be given through someone else’s faith?", a: "Yes: the paralytic is forgiven when Jesus sees “their faith” — that of those carrying him (Mark 2:5); the centurion’s servant is healed through his master’s faith (Matt 8:13); the son of the widow of Nain is raised out of compassion for his mother (Luke 7:13-15). This is the basis of the godparents’ role at baptism." },
    { c: 10, n: 256, q: "Does Scripture attest the baptism of children?", a: "The Apostles baptised whole families, which doubtless included children: the household of Cornelius (Acts 10:48), Lydia and her household (Acts 16:15), the Philippian jailer “and all his” (Acts 16:33), the household of Stephanas (1 Cor 1:16)." },
    { c: 10, n: 257, q: "Does Tradition attest the baptism of children?", a: "Yes, abundantly. St Irenaeus of Lyons (2nd century) speaks of Christ coming to save “infants, children, youths and the old”; Origen (3rd century) states that the custom of baptising little children comes from the Apostles." },
    { c: 10, n: 258, q: "Why are there prayers of exorcism before Baptism?", a: "To drive out the hold of evil over the human heart. Their power is the name of Jesus Christ spoken with faith: “In my name shall they cast out devils” (Mark 16:17)." },
    { c: 10, n: 259, q: "Where does the power of the prayer of exorcism come from?", a: "From the name of Jesus Christ spoken with faith: “In my name shall they cast out devils” (Mark 16:17)." },
    { c: 10, n: 260, q: "What power does the sign of the cross have?", a: "The same as the name of Christ invoked with faith. “Let us not be ashamed to confess the Crucified: let us boldly make the sign of the cross on our forehead and on everything — on the bread we eat, on the cup, as we come in and go out” (St Cyril of Jerusalem). Christians have crossed themselves since the Apostles." },
    { c: 10, n: 261, q: "Since when have Christians made the sign of the cross?", a: "Since apostolic times, as Tertullian and St Dionysius the Areopagite already attest." },
    { c: 10, n: 262, q: "What do the white garment and the baptismal cross mean?", a: "The white garment signifies purity of soul and of Christian life. The baptismal cross, worn throughout life, recalls Christ’s words: “If any man will come after me, let him… take up his cross” (Matt 16:24)." },
    { c: 10, n: 263, q: "Why is a cross given to the newly baptised?", a: "So that he may always remember Christ’s words: “If any man will come after me, let him deny himself, and take up his cross, and follow me” (Matt 16:24). The baptismal cross is worn throughout life." },
    { c: 10, n: 264, q: "Why is Baptism not repeated?", a: "Because it is a spiritual birth: one is born only once." },
    { c: 10, n: 265, q: "What happens to sins committed before Baptism?", a: "God in his mercy forgives them all and never remembers them again." },
    { c: 10, n: 266, q: "Is sin more serious after Baptism?", a: "Yes, in a sense: the baptised has received special help from God to do good. “If after they have escaped the pollutions of the world through the knowledge of the Lord… they are again entangled therein, the latter end is worse with them than the beginning” (2 Pet 2:20). Hence the importance of confession." },
    { c: 10, n: 267, q: "Can sins be forgiven after Baptism?", a: "Yes, through the “baptism of tears”: the sacrament of Confession." },
    { c: 10, n: 268, q: "What is Chrismation?", a: "The sacrament through which the baptised receives the gifts of the Holy Spirit by anointing with holy chrism, a fragrant oil, with the words: “The seal of the gift of the Holy Spirit.”" },
    { c: 10, n: 269, q: "What does Chrismation give inwardly?", a: "The gifts of the Spirit, which strengthen and establish the Christian for spiritual struggle: “He which… hath anointed us, is God; who hath also sealed us, and given the earnest of the Spirit in our hearts” (2 Cor 1:21-22). This gift is a pledge to be made fruitful throughout life." },
    { c: 10, n: 270, q: "Where does the anointing with holy chrism come from?", a: "The first Christians received the Spirit through the laying-on of the Apostles’ hands (Acts 8:17). As Christians multiplied, their successors handed on this gift through anointing with chrism, prepared to this day from dozens of ingredients and consecrated by the patriarchs." },
    { c: 10, n: 271, q: "What is special about holy chrism?", a: "It is a fragrant oil made of many ingredients (up to some sixty: oil, balsams, resins, aromatic plants), prepared and consecrated by the patriarch or primate of the local Church, successor of the Apostles — usually during Holy Week." },
    { c: 10, n: 272, q: "Why are different parts of the body anointed?", a: "The forehead, to sanctify the mind and thoughts; the eyes, ears and lips, to sanctify the senses; the chest, to sanctify the heart; the hands and feet, to sanctify our deeds and our paths." },
    { c: 10, n: 273, q: "What is the Eucharist?", a: "From the Greek for “thanksgiving”: the sacrament in which, under the forms of bread and wine, the faithful receive the true Body and true Blood of Christ for eternal life. It is the “sacrament of sacraments”, at the centre of the whole life of the Church." },
    { c: 10, n: 274, q: "How was the Eucharist instituted?", a: "By Christ at the Last Supper: “Take, eat; this is my body… Drink ye all of it; for this is my blood of the new testament, which is shed for many for the remission of sins” (Matt 26:26-28). These words are sung at every Liturgy." },
    { c: 10, n: 275, q: "What was the Passover meal of the Old Covenant?", a: "The Hebrews ate the Passover lamb in memory of the night when the lamb’s blood had saved them in Egypt (Exod 12). This lamb foreshadowed Christ, “a lamb without blemish and without spot” (1 Pet 1:19)." },
    { c: 10, n: 276, q: "What is the deepest meaning of the Eucharist?", a: "To receive Christ himself into one’s whole being, body, soul and spirit: “Except ye eat the flesh of the Son of man, and drink his blood, ye have no life in you” (John 6:53)." },
    { c: 10, n: 277, q: "What is the link between the Last Supper and the Liturgy each Sunday?", a: "The Eucharist is not merely a memorial of the Last Supper: it is the same Supper, which Christ has celebrated without interruption since that night, and to which he invites us each time." },
    { c: 10, n: 278, q: "How often should one receive communion?", a: "The Fathers advise receiving communion as often as possible, preparing for it worthily. The catechism suggests at least every three weeks as a guide; the rhythm is set with one’s spiritual father." },
    { c: 10, n: 279, q: "How should one prepare for communion?", a: "Be reconciled with everyone and forgive; cleanse one’s conscience through confession; read the prayers of preparation; fast according to custom; arrive at the beginning of the Liturgy and take part attentively." },
    { c: 10, n: 280, q: "What place does the Eucharist hold among the services?", a: "The central place. It is celebrated during the “Divine Liturgy” (from the Greek <em>leitourgia</em>, “common work”): the common work of God and his people." },
    { c: 10, n: 281, q: "Can one receive communion unworthily?", a: "Yes: the Eucharist is not a magic act. It requires a disposed heart and a will turned towards God. “Let a man examine himself, and so let him eat of that bread, and drink of that cup” (1 Cor 11:28)." },
    { c: 10, n: 282, q: "Do the bread and wine truly become the Body and Blood of Christ?", a: "Yes. The Church has always confessed that the Gifts are not merely a symbol or an image: by the action of the Holy Spirit they become the true Body and true Blood of Christ, and our union with him is real." },
    { c: 10, n: 283, q: "What does the Eucharist bring together?", a: "Heaven and earth, past, present and future: in it the faithful sing with the angels, commemorate the whole history of salvation — even Christ’s second coming — and already taste the Kingdom." },
    { c: 10, n: 284, q: "What is Confession?", a: "The sacrament through which the Christian receives from God forgiveness of the sins he confesses, through the prayer of the priest. Christ gave the Apostles this power: “Whose soever sins ye remit, they are remitted unto them” (John 20:23)." },
    { c: 10, n: 285, q: "Where does the sacrament of Confession come from?", a: "St John the Baptist gave its figure: the crowds came to him “confessing their sins” (Mark 1:5). Christ took up his preaching: “Repent: for the kingdom of heaven is at hand” (Matt 4:17)." },
    { c: 10, n: 286, q: "How was this sacrament instituted?", a: "The risen Christ breathed on the Apostles: “Receive ye the Holy Spirit: whose soever sins ye remit, they are remitted unto them” (John 20:22-23). This power is handed on to their successors." },
    { c: 10, n: 287, q: "What is the deepest meaning of repentance?", a: "In Greek <em>metanoia</em>, “change of mind”: a conversion, a turning of one’s whole life and thinking towards God, not merely regret." },
    { c: 10, n: 288, q: "What does repentance begin with?", a: "“The beginning of repentance is the condemnation of one’s sins. Condemn your sins: that is enough for the Lord to justify you” (St John Chrysostom). It is a matter of condemning sin, not of hating oneself." },
    { c: 10, n: 289, q: "What are the stages of repentance?", a: "To stop and look at one’s life in the light of God; to acknowledge one’s sins, like the prodigal son who “came to himself” (Luke 15:17); to decide to return to the Father; to confess one’s faults; to change one’s life with the help of grace." },
    { c: 10, n: 290, q: "What are “fruits worthy of repentance”?", a: "The virtue opposed to the sin committed: “You stole? Give. You spoke idly? Keep silence. You offended? Come to help.”" },
    { c: 10, n: 291, q: "When does repentance end?", a: "Never, in this life: “My sin is ever before me” (Ps 51:3). The Sayings of the Desert Fathers tell how Abba Sisoes, at the point of death, his face shining, still begged the angels: “Give me a little time to repent.” — “You have no need to repent, Father!” — “Truly, I do not know whether I have even begun.”" },
    { c: 10, n: 292, q: "How often should one go to confession?", a: "As regularly as one washes: confession is hygiene and healing for the soul. “Have you sinned? Come into the church… Here is a physician, not a judge” (St John Chrysostom)." },
    { c: 10, n: 293, q: "What is Ordination?", a: "The sacrament through which the Holy Spirit establishes a Christian as bishop, priest or deacon, through the laying-on of hands of the successors of the Apostles, “to feed the church of God” (Acts 20:28)." },
    { c: 10, n: 294, q: "What does “feeding the Church” mean?", a: "Teaching the faithful and helping them grow in faith, piety and virtue, in the image of the Good Shepherd." },
    { c: 10, n: 295, q: "What is the difference between deacon, priest and bishop?", a: "The deacon serves at the celebration of the sacraments without performing them; the priest, delegated by the bishop, celebrates the sacraments; the bishop celebrates the sacraments and can also hand on this power by ordaining." },
    { c: 10, n: 296, q: "What is the “royal priesthood” of all the faithful?", a: "All the baptised are “a royal priesthood” (1 Pet 2:9): they can address God directly and offer him spiritual sacrifices on the altar of their heart — prayer, charity, praise. This common priesthood does not replace the ordained priesthood; it is its foundation." },
    { c: 10, n: 297, q: "What is Marriage?", a: "The sacrament in which, on the free consent of the betrothed, God blesses their union in the image of the union of Christ and the Church, and gives them the grace of unity, faithfulness, and the birth and upbringing of children." },
    { c: 10, n: 298, q: "Why is Marriage a mystery?", a: "Because in it man and woman mysteriously become “one flesh”: “This is a great mystery: but I speak concerning Christ and the church” (Eph 5:31-32)." },
    { c: 10, n: 299, q: "Where does Marriage come from?", a: "From paradise: God created woman and brought her to the man, who exclaims: “This is now bone of my bones, and flesh of my flesh!” (Gen 2:23). Marriage is part of God’s original plan, even before the fall." },
    { c: 10, n: 300, q: "What is the purpose of Marriage?", a: "That man and woman become one, in the image of the Trinity united in love, and help each other on the way of salvation. Children are its fruit and blessing." },
    { c: 10, n: 301, q: "Is a marriage without children less of a marriage?", a: "No. Couples who cannot have children have the same possibility of fulfilling God’s plan for marriage: “They are no more twain, but one flesh” (Matt 19:6)." },
    { c: 10, n: 302, q: "Must everyone marry?", a: "No. Consecrated virginity, notably in monastic life, is a higher calling, but reserved for those “to whom it is given” (Matt 19:11)." },
    { c: 10, n: 303, q: "What is the Anointing of the sick?", a: "The sacrament in which, through anointing with oil, the sick person receives God’s grace for the healing of soul and body. It goes back to the Apostles: “Is any sick among you? let him call for the elders of the church” (Jas 5:14)." },
    { c: 10, n: 304, q: "Where does the Anointing of the sick come from?", a: "From the Apostles, who “anointed with oil many that were sick, and healed them” (Mark 6:13), and from St James: “Is any sick among you? let him call for the elders of the church; and let them pray over him, anointing him with oil in the name of the Lord” (Jas 5:14-15)." },
    { c: 10, n: 305, q: "For whom is the Anointing of the sick intended?", a: "For the sick, who receive comfort in it and, according to God’s will, healing. The body deserves care, for it is not a shell we shall cast off: we shall live with it eternally after the resurrection. (In Russian practice, the Church also gives the Anointing to all the faithful on Great Wednesday, for the healing of the soul.)" },
    { c: 11, n: 306, q: "What is the resurrection of the dead?", a: "The universal event in which the souls of all people will rejoin their own bodies, now incorruptible: “This corruptible must put on incorruption” (1 Cor 15:53)." },
    { c: 11, n: 307, q: "When will it take place?", a: "At Christ’s second coming and the Last Judgement." },
    { c: 11, n: 308, q: "Will everyone rise again?", a: "Yes, all. And those still alive will be changed “in a moment, in the twinkling of an eye” (1 Cor 15:52)." },
    { c: 11, n: 309, q: "How will the bodies rise?", a: "They will be our own bodies, but transfigured, incorruptible, spiritual, in the image of the glorious body of the risen Christ. The prophet Ezekiel foretold it in the vision of the dry bones coming back to life (Ezek 37)." },
    { c: 11, n: 310, q: "What will become of this world?", a: "It will be transformed, purified as by fire: “I saw a new heaven and a new earth” (Rev 21:1)." },
    { c: 11, n: 311, q: "Where are the souls of the departed before the resurrection?", a: "The souls of the righteous already taste the joy of paradise and await the whole Church joining them for the fullness of the reward (Heb 11:40). Others wait in sorrow. The prayers of the Church and the Liturgy can bring them relief." },
    { c: 12, n: 312, q: "What is “the life of the age to come”?", a: "The life that will follow the resurrection of the dead and the Judgement: eternal life with God, in a renewed world." },
    { c: 12, n: 313, q: "What will be the lot of those who refuse God?", a: "Scripture speaks of “everlasting punishment” (Matt 25:46). The Fathers explain that the same light of God will be joy for those who love it and burning for those who refuse it. “God warns people of Gehenna so that they may escape it” (St John Chrysostom)." },
    { c: 12, n: 314, q: "Will the punishments be the same for all?", a: "No: God “shall reward every man according to his works” (Matt 16:27). The servant who knew his lord’s will and did not do it will be judged more severely (Luke 12:47-48)." },
    { c: 12, n: 315, q: "What will the joy of the righteous be?", a: "To see God “face to face” (1 Cor 13:12), in a joy that “eye hath not seen, nor ear heard” (1 Cor 2:9). “All will see the sweet face of Jesus Christ” (St Irenaeus of Lyons)." },
    { c: 12, n: 316, q: "Will the rewards be equal?", a: "No: “There is one glory of the sun, and another glory of the moon, and another glory of the stars” (1 Cor 15:41). “In my Father’s house are many mansions” (John 14:2). But each will be filled according to his or her measure." },
    { c: 12, n: 317, q: "How does thinking about the end of time help us live?", a: "Remembering death, the resurrection and the Judgement helps us to detach ourselves from passing goods, to keep a pure heart, to be comforted in trials and to live each day in the presence of God. “Remember the end, and thou shalt never do amiss” (Sir 7:36)." }
  ],
  creedLines: [
      "The Symbol of Faith: its meaning, its origin, the councils.",
      "I believe in one God, the Father Almighty, Maker of heaven and earth, and of all things visible and invisible.",
      "And in one Lord Jesus Christ, the Son of God, the Only-begotten, begotten of the Father before all ages…",
      "Who for us men and for our salvation came down from heaven, and was incarnate of the Holy Spirit and the Virgin Mary, and became man.",
      "And was crucified also for us under Pontius Pilate, and suffered, and was buried.",
      "And the third day he rose again, according to the Scriptures.",
      "And ascended into heaven, and sits at the right hand of the Father.",
      "And he shall come again with glory to judge the living and the dead, whose kingdom shall have no end.",
      "And in the Holy Spirit, the Lord, the Giver of Life, who proceeds from the Father…",
      "In one Holy, Catholic and Apostolic Church.",
      "I acknowledge one baptism for the remission of sins.",
      "I look for the resurrection of the dead…",
      "… and the life of the age to come. Amen."
  ]
};
